  args: {
    product: MOCK_LINE_ITEM,
    primaryAction: <button type="button">Remove</button>,
    secondaryActions: <button type="button">Edit</button>,
    message: { variant: 'error', text: 'Quantity unavailable in this size' },
  },
};

/** Warning variant — max-quantity messaging. Gap stays at the default 12px (only `error` widens it). */
export const WithWarningMessage: Story = {
  args: {
    product: MOCK_LINE_ITEM,
    primaryAction: <button type="button">Remove</button>,
    secondaryActions: <button type="button">Edit</button>,
    message: { variant: 'warning', text: 'Maximum purchase quantity reached for this size' },
  },
};

